-- Forward-only A11-A14 runtime closure. Nullable line references preserve posted history.
ALTER TYPE "PurchaseClassification" ADD VALUE IF NOT EXISTS 'FIXED_ASSET';
ALTER TABLE "commercial_document_lines" ADD COLUMN "warehouseId" UUID, ADD COLUMN "batchId" UUID, ADD COLUMN "serialNumberId" UUID, ADD COLUMN "stockReturnQuantity" DECIMAL(18,4) NOT NULL DEFAULT 0, ADD COLUMN "cessRate" DECIMAL(7,4) NOT NULL DEFAULT 0;
ALTER TABLE "commercial_document_lines" ADD CONSTRAINT "commercial_line_stock_return_valid" CHECK ("stockReturnQuantity" >= 0 AND "stockReturnQuantity" <= "quantity");
ALTER TABLE "commercial_document_lines" ADD CONSTRAINT "commercial_line_warehouse_company_fk" FOREIGN KEY ("companyId","warehouseId") REFERENCES "warehouses"("companyId","id") ON DELETE RESTRICT ON UPDATE RESTRICT;
ALTER TABLE "commercial_document_lines" ADD CONSTRAINT "commercial_line_batch_company_fk" FOREIGN KEY ("companyId","batchId") REFERENCES "inventory_batches"("companyId","id") ON DELETE RESTRICT ON UPDATE RESTRICT;
ALTER TABLE "commercial_document_lines" ADD CONSTRAINT "commercial_line_serial_company_fk" FOREIGN KEY ("companyId","serialNumberId") REFERENCES "inventory_serial_numbers"("companyId","id") ON DELETE RESTRICT ON UPDATE RESTRICT;
ALTER TABLE "inventory_batches" ADD CONSTRAINT "inventory_batches_company_fk" FOREIGN KEY ("companyId") REFERENCES "companies"("id") ON DELETE RESTRICT ON UPDATE RESTRICT;
ALTER TABLE "inventory_serial_numbers" ADD CONSTRAINT "inventory_serial_company_fk" FOREIGN KEY ("companyId") REFERENCES "companies"("id") ON DELETE RESTRICT ON UPDATE RESTRICT;
ALTER TABLE "stock_movements" ADD CONSTRAINT "stock_movements_batch_fk" FOREIGN KEY ("companyId","batchId") REFERENCES "inventory_batches"("companyId","id") ON DELETE RESTRICT ON UPDATE RESTRICT;
ALTER TABLE "stock_movements" ADD CONSTRAINT "stock_movements_serial_fk" FOREIGN KEY ("companyId","serialNumberId") REFERENCES "inventory_serial_numbers"("companyId","id") ON DELETE RESTRICT ON UPDATE RESTRICT;
ALTER TABLE "stock_movements" ADD CONSTRAINT "stock_movements_creator_fk" FOREIGN KEY ("companyId","createdById") REFERENCES "users"("companyId","id") ON DELETE RESTRICT ON UPDATE RESTRICT;
ALTER TABLE "product_prices" ADD CONSTRAINT "product_prices_customer_fk" FOREIGN KEY ("companyId","customerId") REFERENCES "customers"("companyId","id") ON DELETE RESTRICT ON UPDATE RESTRICT;
CREATE INDEX "inventory_batches_expiry_idx" ON "inventory_batches"("companyId","expiryDate"); CREATE INDEX "inventory_serial_expiry_idx" ON "inventory_serial_numbers"("companyId","expiryDate"); CREATE INDEX "stock_movements_serial_state_idx" ON "stock_movements"("companyId","serialNumberId","movementDate"); CREATE INDEX "commercial_lines_warehouse_product_idx" ON "commercial_document_lines"("companyId","warehouseId","productId");
ALTER TABLE "assets" ADD CONSTRAINT "assets_purchase_document_fk" FOREIGN KEY ("companyId","purchaseDocumentId") REFERENCES "commercial_documents"("companyId","id") ON DELETE RESTRICT ON UPDATE RESTRICT; ALTER TABLE "assets" ADD CONSTRAINT "assets_purchase_line_fk" FOREIGN KEY ("companyId","purchaseDocumentLineId") REFERENCES "commercial_document_lines"("companyId","id") ON DELETE RESTRICT ON UPDATE RESTRICT; ALTER TABLE "assets" ADD CONSTRAINT "assets_assignee_fk" FOREIGN KEY ("companyId","assignedUserId") REFERENCES "users"("companyId","id") ON DELETE RESTRICT ON UPDATE RESTRICT; ALTER TABLE "assets" ADD CONSTRAINT "assets_creator_fk" FOREIGN KEY ("companyId","createdById") REFERENCES "users"("companyId","id") ON DELETE RESTRICT ON UPDATE RESTRICT; ALTER TABLE "assets" ADD CONSTRAINT "assets_asset_ledger_fk" FOREIGN KEY ("companyId","assetLedgerId") REFERENCES "ledger_accounts"("companyId","id") ON DELETE RESTRICT ON UPDATE RESTRICT; ALTER TABLE "assets" ADD CONSTRAINT "assets_accumulated_ledger_fk" FOREIGN KEY ("companyId","accumulatedDepreciationLedgerId") REFERENCES "ledger_accounts"("companyId","id") ON DELETE RESTRICT ON UPDATE RESTRICT; ALTER TABLE "assets" ADD CONSTRAINT "assets_depreciation_expense_ledger_fk" FOREIGN KEY ("companyId","depreciationExpenseLedgerId") REFERENCES "ledger_accounts"("companyId","id") ON DELETE RESTRICT ON UPDATE RESTRICT;
