CREATE INDEX "assets_purchase_document_idx" ON "assets"("companyId","purchaseDocumentId"); CREATE INDEX "assets_assignee_idx" ON "assets"("companyId","assignedUserId");
INSERT INTO "ledger_accounts" ("id","companyId","code","name","accountClass","normalBalance","systemKey","isSystem","isActive","allowPosting","createdAt","updatedAt") SELECT gen_random_uuid(),c.id,v.code,v.name,v.class::"LedgerAccountClass",v.normal::"NormalBalanceSide",v.key,true,true,true,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP FROM "companies" c CROSS JOIN (VALUES ('1460','Inventory Asset','ASSET','DEBIT','INVENTORY_ASSET'),('1470','CGST ITC','ASSET','DEBIT','CGST_ITC'),('1471','SGST ITC','ASSET','DEBIT','SGST_ITC'),('1472','IGST ITC','ASSET','DEBIT','IGST_ITC'),('1473','CESS ITC','ASSET','DEBIT','CESS_ITC'),('2110','CGST Payable','LIABILITY','CREDIT','CGST_PAYABLE'),('2111','SGST Payable','LIABILITY','CREDIT','SGST_PAYABLE'),('2112','IGST Payable','LIABILITY','CREDIT','IGST_PAYABLE'),('2113','CESS Payable','LIABILITY','CREDIT','CESS_PAYABLE'),('2120','TDS Payable','LIABILITY','CREDIT','TDS_PAYABLE'),('2130','TCS Payable','LIABILITY','CREDIT','TCS_PAYABLE'),('5200','Cost of Goods Sold','EXPENSE','DEBIT','COGS')) v(code,name,class,normal,key) WHERE c."productEdition" IN ('SALESPUNCH360_ACCOUNT','SALESPUNCH360_PLUS') ON CONFLICT ("companyId","systemKey") DO NOTHING;
